import{z as o,x as s,o as B,c as d,q as n,j as t,D as A,d as e,s as i,S as r,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"自训练数据的污染","description":"","frontmatter":{"title":"自训练数据的污染","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/contamination-loop.md","filePath":"llm/contamination-loop.md","lastUpdated":1791063341000}'),m={name:"llm/contamination-loop.md"};function D(p,E,C,u,h,F){const l=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="自训练数据的污染" tabindex="-1">自训练数据的污染 <a class="header-anchor" href="#自训练数据的污染" aria-label="Permalink to &quot;自训练数据的污染&quot;">​</a></h1><div class="epigraph"><p>去重把住的是语料入口，闭环在每一轮重新发明泄漏：模型把评测题改写成新训练样本，n-gram 看不见的等价类逐轮生长。</p><footer>—— Carlini 等, Deduplicating Training Data Makes Language Models Better（2023）；Golchin 与 Surdeanu, Time Travel in LLMs（2023）</footer></div><p><a href="/llm/player-selection-bias">上一课</a>的失效在对手侧；本课转向数据侧：评测集泄漏进训练闭环时，所有迭代指标一起说谎——通过率的增长是记忆，不是能力。传统污染治理发生在语料入库：对基准集做精确子串或 n-gram 重叠（如 13-gram）过滤。自训练闭环让这套防线失效的方式，是污染发生在入库之后、生成阶段之内：每一轮训练都在生产表面全新、语义等价的泄漏样本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>泄漏路径有四条。预训练语料本就含基准题及其解答，教师与学生都见过。合成数据的提示以网络爬取的种子起步，种子里的评测题被改写进生成提示。蒸馏教师的输出原样带出评测题——<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>已因此要求蒸馏集去污染。最隐蔽的是闭环自己的再生：模型对评测题生成高置信答案，这些答案连同改写的题面进入下一轮训练数据；每过一轮，题面表述离原文更远一层，表面 n-gram 重叠趋零，语义等价不变。不这么做会错在哪：只做入库去重的团队会看到「每轮都涨」的通过率，并把污染驱动的记忆当成闭环在工作。</p><p><span class="marginnote">「等价类」在这里指字面完全不同、但考的是同一道题的所有变体：换变量名、改题干说法、调换选项顺序都算。过滤工具看得见字面，看不见意思，所以等价类会一轮轮长大——这正是闭环污染比入库污染难治的根本原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>闭环内的对策是把过滤从「入库一次」改成「每轮一道」。每轮生成数据对基准索引做两级匹配：n-gram 级抓原文复制，嵌入近邻抓改写；命中样本连同其近邻回溯到提示源头，提示含评测内容则整批丢弃。金丝雀是闭环里少数可主动部署的仪器：在每轮训练数据埋入唯一 GUID 串，事后用补全探针测是否被背出——背出说明记忆化在环内发生，且规模可估。更结构性的做法是保持一个永不进入闭环、永不公开的私有 held-out，并用训练截止之后新出的评测集做时间切分验证；三者的交集才是可信读数。</p>',8)),(B(),t(r,null,{default:A(()=>[i(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E6%9C%AC%E8%BD%AE%E7%94%9F%E6%88%90%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20NG%5B%22n-gram%20%E5%AF%B9%E5%9F%BA%E5%87%86%E7%B4%A2%E5%BC%95%22%5D%0A%20%20GEN%20--%3E%20EMB%5B%22%E5%B5%8C%E5%85%A5%E8%BF%91%E9%82%BB%E6%8A%93%E6%94%B9%E5%86%99%22%5D%0A%20%20NG%20--%3E%20HIT%7B%22%E5%91%BD%E4%B8%AD%3F%22%7D%0A%20%20EMB%20--%3E%20HIT%0A%20%20HIT%20--%3E%7C%E6%98%AF%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E5%B9%B6%E5%9B%9E%E6%BA%AF%E6%8F%90%E7%A4%BA%E6%BA%90%22%5D%0A%20%20HIT%20--%3E%7C%E5%90%A6%7C%20TRAIN%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%E8%AE%AD%E7%BB%83%22%5D%0A%20%20TRAIN%20--%3E%20CAN%5B%22%E9%87%91%E4%B8%9D%E9%9B%80%E8%A1%A5%E5%85%A8%E6%8E%A2%E9%92%88%22%5D%0A%20%20CAN%20--%3E%20ALARM%7B%22%E8%83%8C%E5%87%BA%3F%22%7D%0A%20%20ALARM%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E6%8A%A5%E8%AD%A6%EF%BC%9A%E6%9C%AC%E8%BD%AE%E5%8F%91%E7%94%9F%E8%AE%B0%E5%BF%86%E5%8C%96%22%5D%0A%20%20ALARM%20--%3E%7C%E5%90%A6%7C%20NEXT%5B%22%E4%BF%A1%E4%BB%BB%E6%9C%AC%E8%BD%AE%E9%80%9A%E8%BF%87%E7%8E%87%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"金丝雀可以想象成往训练数据里掺一粒有编号的沙：埋进一串随机字符，训练结束后只给模型看前半截让它补全。若它能一字不差补出来，说明模型在背而不是在想——同一机理也适用于它见过的评测题。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"污染在闭环里是复合过程。第一轮的泄漏改变模型对评测题的输出分布；第二轮它生成更多与评测题同分布的内容；第三轮这些内容成了「验证通过的训练数据」——同时验证器也坏了：法官见过这些题，会把背出来的完成判为正确。传统去重失效的根本原因是它假设污染态在数据进入管线前就固定；闭环的污染是生成动力学的一部分，每轮都在创造新的等价类。这与模型坍缩是同一枚硬币的两面：多样性与尾部在收缩，而高频部分——恰是评测题这类被反复生成的样本——在增密。指标上表现为：训练侧通过率、裁判分、环内奖励同涨，唯独外生 held-out 不动。",-1)),(B(),t(r,null,{default:A(()=>[i(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E7%AC%AC%201%20%E8%BD%AE%3A%E5%9F%BA%E5%87%86%E9%A2%98%E6%B3%84%E6%BC%8F%E8%BF%9B%E8%AE%AD%E7%BB%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20M1%5B%22%E6%A8%A1%E5%9E%8B%E5%AF%B9%E8%80%83%E9%A2%98%E7%9A%84%E8%BE%93%E5%87%BA%E5%88%86%E5%B8%83%E8%A2%AB%E6%8B%89%E9%AB%98%22%5D%0A%20%20M1%20--%3E%20L2%5B%22%E7%AC%AC%202%20%E8%BD%AE%3A%E7%94%9F%E6%88%90%E6%9B%B4%E5%A4%9A%E4%B8%8E%E8%80%83%E9%A2%98%E5%90%8C%E5%88%86%E5%B8%83%E7%9A%84%E5%86%85%E5%AE%B9%22%5D%0A%20%20L2%20--%3E%20M2%5B%22%E5%86%85%E5%AE%B9%E8%A2%AB%E5%BD%93%E6%88%90%E5%90%88%E6%A0%BC%E7%9A%84%E5%90%88%E6%88%90%E6%95%B0%E6%8D%AE%22%5D%0A%20%20M2%20--%3E%20L3%5B%22%E7%AC%AC%203%20%E8%BD%AE%3A%E6%94%B9%E5%86%99%E6%A0%B7%E6%9C%AC%E7%A6%BB%E5%8E%9F%E6%96%87%E6%9B%B4%E8%BF%9C%22%5D%0A%20%20L3%20--%3E%20Z%5B%22n-gram%20%E9%87%8D%E5%8F%A0%E8%B6%8B%E9%9B%B6%2C%E8%AF%AD%E4%B9%89%E7%AD%89%E4%BB%B7%E4%B8%8D%E5%8F%98%22%5D%0A%20%20Z%20--%3E%20V%5B%22%E6%B3%95%E5%AE%98%E8%A7%81%E8%BF%87%E8%80%83%E9%A2%98%2C%E8%83%8C%E8%AF%B5%E8%A2%AB%E5%88%A4%E6%AD%A3%E7%A1%AE%22%5D%0A%20%20V%20--%3E%20X%5B%22%E5%A4%96%E7%94%9F%20held-out%20%E4%B8%8D%E5%8A%A8%2C%E7%8E%AF%E5%86%85%E6%8C%87%E6%A0%87%E5%85%A8%E6%B6%A8%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=n('<p><span class="marginnote">初学者容易以为阈值调松一点、多放几篇相似样本进来只是小事。实际上每漏过一篇被改写的评测题，下一轮模型就会围绕它生成一批新的等价变体——单轮漏一个，三轮后可能是一片。阈值要按多轮累积的后果算账，而不是只看本轮的假阳率。</span></p><p><span class="marginnote">Carlini 等人 2023 的量化：对 C4 做精确子串去重后，可被提示拉出的记忆化样本降到约十分之一，训练-测试重叠同步下降。这是入库侧去重的收益上限——它对闭环内新生的改写无能为力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>过滤器有假阴也有假阳：改写检测的阈值调紧，合法的同类题被误杀，课程多样性受损；调松，泄漏漏网。披露与指标卫生是底线：报告时分开「可能污染集」与「清洁集」的通过率，标注每轮数据对基准索引的最大相似度。已泄漏的题几乎无法从模型里移除——重训或拒绝采样只能压低触发概率。任何「我们每轮都涨」的闭环报告，第一个该问的是基准索引的匹配阈值与金丝雀探针的结果；答不出，读数就不进仪表。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>污染可以发生在生成阶段：闭环每轮制造 n-gram 全新、语义相同的样本。</li><li>过滤要每轮做，n-gram 与嵌入近邻两级，命中须回溯提示源头。</li><li>金丝雀、私有 held-out、截止后新评测是三种外生读数，取交集。</li><li>法官被污染时验证器失效，通过率与判分一起虚高。</li><li>出处：Carlini 等（2023）；Golchin 与 Surdeanu（2023）；蒸馏集去污染要求见推理蒸馏课。</li></ul>',6))])}const f=o(m,[["render",D]]);export{T as __pageData,f as default};
